package android.app;public class PictureInPictureParams{public Boolean seamless;public android.util.Rational ratio;public android.graphics.Rect hint;public static class Builder{PictureInPictureParams p=new PictureInPictureParams();public Builder setSeamlessResizeEnabled(boolean value){p.seamless=value;return this;}public Builder setAspectRatio(android.util.Rational r){p.ratio=r;return this;}public Builder setSourceRectHint(android.graphics.Rect r){p.hint=r;return this;}public PictureInPictureParams build(){return p;}}}